using System;
using System.IO;
using System.Linq;
using System.Text.Json;
using HeroCat.Sim.Content;

namespace HeroCat.Sim.Tests
{
    /// <summary>
    /// Reader for Fixtures/Gacha/vectors.json (generated by `HeroCat.Bots gacha-vectors --update`).
    /// Also linked into HeroCat.Server.Tests, so it uses only the Sim types the server compiles.
    /// </summary>
    internal sealed class GachaVectorFile
    {
        public sealed record Pull(Rarity Tier, string HeroId, int PityAfter);
        public sealed record Vector(int ProfileSeed, ulong StreamSeed, Pull[][] Batches);

        public string ContentHash { get; private set; }
        public string BannerId { get; private set; }
        public int PullsPerSeed { get; private set; }
        public Vector[] Vectors { get; private set; }

        public const string Regenerate = "dotnet run --project src/HeroCat.Bots -- gacha-vectors --update";

        public static GachaVectorFile LoadFromRepo(string startDirectory)
        {
            for (var dir = new DirectoryInfo(startDirectory); dir != null; dir = dir.Parent)
            {
                string p = Path.Combine(dir.FullName, "Fixtures", "Gacha", "vectors.json");
                if (File.Exists(p)) return Load(p);
            }
            throw new FileNotFoundException("Fixtures/Gacha/vectors.json not found above " + startDirectory);
        }

        public static GachaVectorFile Load(string path)
        {
            using var doc = JsonDocument.Parse(File.ReadAllText(path));
            var root = doc.RootElement;
            if (root.GetProperty("format").GetInt32() != 1) throw new FormatException("unsupported vectors format");
            return new GachaVectorFile
            {
                ContentHash = root.GetProperty("contentHash").GetString(),
                BannerId = root.GetProperty("bannerId").GetString(),
                PullsPerSeed = root.GetProperty("pullsPerSeed").GetInt32(),
                Vectors = root.GetProperty("vectors").EnumerateArray().Select(v => new Vector(
                    v.GetProperty("profileSeed").GetInt32(),
                    ulong.Parse(v.GetProperty("streamSeed").GetString(), System.Globalization.CultureInfo.InvariantCulture),
                    v.GetProperty("batches").EnumerateArray().Select(b => b.EnumerateArray().Select(p => new Pull(
                        Enum.Parse<Rarity>(p[0].GetString()), p[1].GetString(), p[2].GetInt32())).ToArray()).ToArray())).ToArray(),
            };
        }
    }
}
